#!/usr/bin/env python3
"""Pin the PDFium release the build hook downloads.

Downloads every archive `hook/build.dart` can fetch from
bblanchon/pdfium-binaries for one release, then writes
`hook/pdfium_archives.dart`: the release and each archive's SHA-256, which the
hook checks before it extracts the library.

Run it from any directory when the release changes:

    python3 flutter/third_party/pdfium_dart/tool/pin_pdfium.py chromium/7811
"""

from __future__ import annotations

import argparse
import hashlib
import sys
import urllib.parse
import urllib.request
from pathlib import Path

PACKAGE = Path(__file__).resolve().parent.parent

# Every `<platform>-<arch>` the hook's `_PdfiumTarget` can name.
TARGETS = (
    "android-arm",
    "android-arm64",
    "android-x64",
    "android-x86",
    "linux-arm",
    "linux-arm64",
    "linux-x64",
    "linux-x86",
    "mac-arm64",
    "mac-x64",
    "win-arm64",
    "win-x64",
    "win-x86",
)


def archive_url(release: str, target: str) -> str:
    tag = urllib.parse.quote(release, safe="")
    return (
        "https://github.com/bblanchon/pdfium-binaries/releases/download/"
        f"{tag}/pdfium-{target}.tgz"
    )


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("release", help="pdfium-binaries tag, e.g. chromium/7811")
    release = parser.parse_args().release

    hashes: dict[str, str] = {}
    for target in TARGETS:
        url = archive_url(release, target)
        print(f"fetching {url}", file=sys.stderr)
        with urllib.request.urlopen(url) as response:
            data = response.read()
        hashes[target] = hashlib.sha256(data).hexdigest()

    tag = release.replace("/", "%2F")
    lines = [
        "// Generated by tool/pin_pdfium.py; do not edit.",
        "",
        "/// The pdfium-binaries release the hook downloads.",
        f"const pdfiumRelease = '{tag}';",
        "",
        "/// SHA-256 of each `pdfium-<platform>-<arch>.tgz` in [pdfiumRelease].",
        "const pdfiumArchiveSha256 = <String, String>{",
        *(f"  '{target}':\n      '{digest}'," for target, digest in hashes.items()),
        "};",
        "",
    ]
    (PACKAGE / "hook" / "pdfium_archives.dart").write_text("\n".join(lines))
    return 0


if __name__ == "__main__":
    sys.exit(main())
